package com.rohit.inventory.controller;
import com.rohit.inventory.dto.response.*; import com.rohit.inventory.service.NotificationService; import java.util.UUID; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/notifications") public class NotificationController { private final NotificationService service; public NotificationController(NotificationService service){this.service=service;} @GetMapping @PreAuthorize("hasAuthority('NOTIFICATION_READ') or hasAuthority('INVENTORY_READ')") public ApiResponse<Page<NotificationResponse>> list(@RequestParam(defaultValue="false")boolean unread,@PageableDefault(size=20,sort="createdAt",direction=Sort.Direction.DESC)Pageable p,@AuthenticationPrincipal UserDetails u){return ApiResponse.success("Notifications retrieved successfully",service.list(u.getUsername(),unread,p));} @GetMapping("/unread-count") @PreAuthorize("hasAuthority('NOTIFICATION_READ') or hasAuthority('INVENTORY_READ')") public ApiResponse<Long> count(@AuthenticationPrincipal UserDetails u){return ApiResponse.success("Unread count retrieved successfully",service.unread(u.getUsername()));} @PostMapping("/{id}/read") @PreAuthorize("hasAuthority('NOTIFICATION_UPDATE') or hasAuthority('INVENTORY_READ')") public ApiResponse<Void> read(@PathVariable UUID id,@AuthenticationPrincipal UserDetails u){service.read(u.getUsername(),id);return ApiResponse.success("Notification marked as read",null);} @PostMapping("/read-all") @PreAuthorize("hasAuthority('NOTIFICATION_UPDATE') or hasAuthority('INVENTORY_READ')") public ApiResponse<Void> readAll(@AuthenticationPrincipal UserDetails u){service.readAll(u.getUsername());return ApiResponse.success("Notifications marked as read",null);} }
